"""Merge user data from three heterogeneous sources with priority-based conflict resolution."""

import json
import re
from pathlib import Path

import pandas as pd

DATA_DIR = Path("/data")
OUTPUT_DIR = Path("/app")

# Unified field -> possible source column names (checked case-insensitively).
FIELD_ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

# Fields that participate in conflict detection (all fields except the merge key).
MERGE_FIELDS = ["name", "email", "created_date", "status"]

# Priority order, highest first.
SOURCES = [
    ("source_a", DATA_DIR / "source_a" / "users.json"),
    ("source_b", DATA_DIR / "source_b" / "users.csv"),
    ("source_c", DATA_DIR / "source_c" / "users.parquet"),
]


def read_source(path: Path) -> pd.DataFrame:
    suffix = path.suffix.lower()
    if suffix == ".json":
        with path.open(encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            # Tolerate {"users": [...]} style payloads.
            for value in data.values():
                if isinstance(value, list):
                    data = value
                    break
        return pd.DataFrame(data)
    if suffix == ".csv":
        return pd.read_csv(path)
    if suffix in (".parquet", ".pq"):
        return pd.read_parquet(path)
    raise ValueError(f"Unsupported source format: {path}")


def normalize_columns(df: pd.DataFrame) -> pd.DataFrame:
    """Rename source-specific columns to the unified schema."""
    lowered = {str(col).strip().lower(): col for col in df.columns}
    renames = {}
    for unified, aliases in FIELD_ALIASES.items():
        for alias in aliases:
            original = lowered.get(alias.lower())
            if original is not None and original not in renames:
                renames[original] = unified
                break
    df = df.rename(columns=renames)
    # Keep only known fields, dropping duplicate unified columns if any.
    df = df.loc[:, [c for c in df.columns if c in FIELD_ALIASES]]
    df = df.loc[:, ~df.columns.duplicated()]
    for field in FIELD_ALIASES:
        if field not in df.columns:
            df[field] = None
    return df[list(FIELD_ALIASES)]


def normalize_status(value):
    """Map assorted active-flag representations to 'active'/'inactive'."""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, (int, float)):
        return "active" if value != 0 else "inactive"
    text = str(value).strip().lower()
    if text in ("true", "1", "yes", "y", "active", "enabled"):
        return "active"
    if text in ("false", "0", "no", "n", "inactive", "disabled"):
        return "inactive"
    return text or None


def normalize_date(value):
    """Return the date as a YYYY-MM-DD string, or None if unparseable/empty."""
    if value is None:
        return None
    if isinstance(value, float) and pd.isna(value):
        return None
    if isinstance(value, (pd.Timestamp,)):
        return value.strftime("%Y-%m-%d")
    text = str(value).strip()
    if not text or text.lower() in ("nan", "nat", "none", "null"):
        return None
    parsed = pd.to_datetime(text, errors="coerce")
    if pd.isna(parsed):
        return None
    return parsed.strftime("%Y-%m-%d")


def normalize_user_id(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    try:
        return int(float(str(value).strip()))
    except (TypeError, ValueError):
        return None


def normalize_frame(df: pd.DataFrame, source: str) -> pd.DataFrame:
    df = normalize_columns(df.copy())
    df["user_id"] = df["user_id"].map(normalize_user_id)
    df = df[df["user_id"].notna()].copy()
    df["user_id"] = df["user_id"].astype("int64")
    df["name"] = df["name"].map(lambda v: None if v is None or (isinstance(v, float) and pd.isna(v)) else str(v).strip())
    df["email"] = df["email"].map(lambda v: None if v is None or (isinstance(v, float) and pd.isna(v)) else str(v).strip())
    df["created_date"] = df["created_date"].map(normalize_date)
    df["status"] = df["status"].map(normalize_status)
    df["_source"] = source
    # One record per user per source (keep the first).
    df = df.drop_duplicates(subset="user_id", keep="first")
    return df


def values_equal(a, b) -> bool:
    return a == b


def main() -> None:
    frames = []
    for source, path in SOURCES:
        frames.append(normalize_frame(read_source(path), source))

    combined = pd.concat(frames, ignore_index=True)

    user_ids = sorted(combined["user_id"].unique().tolist())
    rows = []
    conflicts = []

    for user_id in user_ids:
        subset = combined[combined["user_id"] == user_id]
        # Map source -> record (dict) for this user.
        by_source = {rec["_source"]: rec for _, rec in subset.iterrows()}

        merged = {"user_id": int(user_id)}
        for field in MERGE_FIELDS:
            available = {
                src: by_source[src][field]
                for src, _ in SOURCES
                if src in by_source and by_source[src][field] is not None
            }

            # Selected value: first non-null according to priority.
            selected = None
            for src, _ in SOURCES:
                if src in available:
                    selected = available[src]
                    break
            merged[field] = selected

            # A conflict exists when sources disagree on a non-null value.
            distinct = set(available.values())
            if len(distinct) > 1:
                conflicts.append(
                    {
                        "user_id": int(user_id),
                        "field": field,
                        "values": {src: available[src] for src, _ in SOURCES if src in available},
                        "selected": selected,
                    }
                )

        rows.append(merged)

    merged_df = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
    merged_df["user_id"] = merged_df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        merged_df[col] = merged_df[col].astype("string")
    merged_df = merged_df.sort_values("user_id").reset_index(drop=True)

    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    merged_df.to_parquet(OUTPUT_DIR / "merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with (OUTPUT_DIR / "conflicts.json").open("w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    print(f"Wrote {len(merged_df)} users and {len(conflicts)} conflicts.")


if __name__ == "__main__":
    main()
